// 1. Localiza a linha de cabeçalho real
// ─────────────────────────────────────────────────────────────
const headerRow = rows.find(r =>
  Object.values(r).some(v => String(v ?? '').trim().toUpperCase() === 'INTERIOR')
);

if (!headerRow) {
  throw new Error('Cabeçalho não encontrado. Verifique o formato da planilha.');
}

const todasAsChaves = Object.keys(headerRow);

const idxInterior = todasAsChaves.findIndex(k =>
  String(headerRow[k] ?? '').trim().toUpperCase() === 'INTERIOR'
);
const idxCapital = todasAsChaves.findIndex(k =>
  String(headerRow[k] ?? '').trim().toUpperCase() === 'CAPITAL'
);

if (idxInterior === -1 || idxCapital === -1) {
  throw new Error('Colunas INTERIOR ou CAPITAL não encontradas no cabeçalho.');
}

const chavesInterior = todasAsChaves.slice(idxInterior - 1, idxCapital - 1);
const chavesCapital  = todasAsChaves.slice(idxCapital - 1);

function montarMapa(chaves) {
  const mapa = {};
  for (const chave of chaves) {
    const nome = String(headerRow[chave] ?? '').trim().toUpperCase();
    if (nome !== '') mapa[nome] = chave;
  }
  return mapa;
}

const mapaInterior = montarMapa(chavesInterior);
const mapaCapital  = montarMapa(chavesCapital);

// ─────────────────────────────────────────────────────────────
// 2. Acréscimo de imposto — sempre lido da planilha, nunca cravado
// ─────────────────────────────────────────────────────────────
function extrairAcrescimo(texto) {
  const m = String(texto ?? '').match(/SOMAR\s+([\d.,]+)\s*%/i);
  if (!m) return 0;
  const pct = parseFloat(m[1].replace(/\./g, '').replace(',', '.'));
  if (!isFinite(pct) || pct <= 0) return 0;
  return pct / 100;
}

// ─────────────────────────────────────────────────────────────
// 3. Extrai os clientes de cada lado
// ─────────────────────────────────────────────────────────────
function extrairLado(mapa) {
  const saida = [];
  const vistos = new Set();

  for (const row of rows) {
    if (row === headerRow) continue;

    const nomeBruto = row[mapa['CLIENTE']];
    if (!nomeBruto) continue;
    const nome = String(nomeBruto).trim();
    if (nome === '' || nome.toUpperCase() === 'CLIENTE') continue;
    if (vistos.has(nome.toUpperCase())) continue;
    vistos.add(nome.toUpperCase());

    const obs = String(row[mapa['TABELA']] ?? '').trim();
    const semTabela = obs.toUpperCase() === 'SEM TABELA';

    saida.push({
      nome,
      sem_tabela: semTabela,
      acrescimo_imposto_pct: semTabela ? 0 : Number((extrairAcrescimo(obs) * 100).toFixed(2)),
    });
  }

  return saida.sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
}

const interior = extrairLado(mapaInterior);
const capital  = extrairLado(mapaCapital);

// ─────────────────────────────────────────────────────────────
// 4. Monta o texto que vai para o prompt
// ─────────────────────────────────────────────────────────────
const marcar = (c) => {
  if (c.sem_tabela) return `${c.nome}  [SEM TABELA]`;
  if (c.acrescimo_imposto_pct > 0) {
    return `${c.nome}  [ACRESCIMO ${String(c.acrescimo_imposto_pct).replace('.', ',')}%]`;
  }
  return c.nome;
};

const formatarLista = (arr) =>
  arr.map((c, i) => `${String(i + 1).padStart(2, '0')}. ${marcar(c)}`).join('\n');

const resumo =
  `CLIENTES — CAPITAL (${capital.length})\n` +
  `${formatarLista(capital)}\n\n` +
  `CLIENTES — INTERIOR (${interior.length})\n` +
  `${formatarLista(interior)}`;

return [{
  json: {
    clientes_capital:  capital.map(c => c.nome),
    clientes_interior: interior.map(c => c.nome),
    clientes_sem_tabela: [...new Set([...capital, ...interior].filter(c => c.sem_tabela).map(c => c.nome))],
    clientes_com_acrescimo: [...new Set([...capital, ...interior]
      .filter(c => c.acrescimo_imposto_pct > 0)
      .map(c => `${c.nome} (${String(c.acrescimo_imposto_pct).replace('.', ',')}%)`))],
    resumo_formatado: resumo
  }
}];

const texto = items[0].json.texto || '';

const textoEscapado = texto.replace(/\*/g, '\\*');

return [{
  json: {
    ...items[0].json,
    texto: textoEscapado
  }
}];

